import type { WixDataBulkInsertOptions } from './types'

/**
 * Options builder for bulk insert operations.
 *
 * Use this builder to configure bulk insert behavior such as hooks suppression.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataBulkInsertOptionsBuilder {
  /**
   * Sets whether to suppress bulk insert hooks.
   *
   * When `true`, the bulk insert runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataBulkInsertOptionsBuilder
  /**
   * Sets whether to include draft items when inserting items in bulk.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataBulkInsertOptionsBuilder
  /**
   * Sets whether to save referenced items when inserting items in bulk.
   */
  withSaveReferences(value: boolean): WixDataBulkInsertOptionsBuilder
  /**
   * Sets whether existing items can be overridden during the bulk insert operation.
   * @internal
   */
  withOverrideExisting(value: boolean): WixDataBulkInsertOptionsBuilder
  /**
   * Builds the bulk insert options object.
   */
  build(): WixDataBulkInsertOptions
}

class WixDataBulkInsertOptionsBuilderImpl
  implements WixDataBulkInsertOptionsBuilder
{
  constructor(private readonly options: WixDataBulkInsertOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataBulkInsertOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataBulkInsertOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withSaveReferences(value: boolean): WixDataBulkInsertOptionsBuilder {
    return this.copy({ saveReferences: value })
  }

  withOverrideExisting(value: boolean): WixDataBulkInsertOptionsBuilder {
    return this.copy({ overrideExisting: value })
  }

  build(): WixDataBulkInsertOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataBulkInsertOptions
  ): WixDataBulkInsertOptionsBuilder {
    return new WixDataBulkInsertOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new bulk insert options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a bulk insert options builder"
 * import { items, BulkInsertOptionsBuilder } from '@wix/data'
 *
 * const options = BulkInsertOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .build()
 *
 * const result = await items.bulkInsert('myCollection', [
 *   { name: 'First item' },
 *   { name: 'Second item' },
 * ], options)
 * ```
 */
export const BulkInsertOptionsBuilder: () => WixDataBulkInsertOptionsBuilder =
  () => new WixDataBulkInsertOptionsBuilderImpl()
